// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);
        LogStub stub = new LogStub();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.SetLogFile(address(stub));
        vm.prank(actor);
        c.Deposit{value: amount}();
        assertTrue(stub.lastSender() == actor && stub.count() == 1);
    }
}

contract LogStub {
    address public lastSender;
    uint public count;
    function AddMessage(address _adr, uint _val, string memory _data) external {
        lastSender = _adr;
        count++;
    }
}
